// Verifies the terminal-punctuation fix before it goes into the worker.
const CASES = [
  { src: 'You are not "too emotional."', out: 'Du bist nicht \u201Ezu emotional\u201C.' },
  { src: 'You are not "too emotional."', out: 'Non sei "troppo emotivo".' },
  { src: 'You are not "too emotional."', out: 'Vous n\u0027\u00EAtes pas \u00AB trop \u00E9motionnel \u00BB.' },
  { src: 'This helps prevent overwhelm.', out: 'So vermeidest du \u00DCberforderung.' },
  { src: 'Managing Emotional Intensity', out: 'Emotionale Intensit\u00E4t steuern.' },
  { src: 'Because you are emotionally responsive, you may benefit from:', out: 'Weil du feinf\u00FChlig bist, hilft dir Folgendes:' }
];
const Q = /["'\u00BB\u201D\u201E\u201F\u201A\u2019\u00AB\u201C]+$/;
const out = [];
for (const c of CASES) {
  const seOld = c.src.trim().slice(-1);
  const seNew = c.src.trim().replace(Q, '').slice(-1);
  const ve = c.out.trim().replace(Q, '').slice(-1);
  function verdict(se) {
    if ((se === '.' || se === ':') && ve !== se) return 'REJECT dropped';
    if ('.:'.indexOf(se) === -1 && '.:'.indexOf(ve) > -1) return 'REJECT added';
    return 'accept';
  }
  out.push({ json: { src: c.src, out: c.out,
    last_char_old: seOld, last_char_new: seNew,
    old_gate: verdict(seOld), new_gate: verdict(seNew) } });
}
return out;
